package mz.bam.seeky.android;
import android.app.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.os.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadow.api.Shadow;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,instrumentedPackages={"com.googlecode.tesseract.android"},shadows={OcrToolsTest.Engine.class,Ocr513Test.Renderer.class,Ocr513Test.Page.class}) @LooperMode(LooperMode.Mode.PAUSED)
public class Ocr513Test {
    @Implements(PdfRenderer.class) public static class Renderer{@Implementation protected void __constructor__(ParcelFileDescriptor descriptor){}@Implementation protected int getPageCount(){return 3;}@Implementation protected PdfRenderer.Page openPage(int page){return Shadow.newInstanceOf(PdfRenderer.Page.class);}@Implementation protected void close(){}}
    @Implements(PdfRenderer.Page.class) public static class Page{@Implementation protected int getWidth(){return 400;}@Implementation protected int getHeight(){return 600;}@Implementation protected void render(Bitmap target,Rect clip,Matrix transform,int mode){target.eraseColor(Color.WHITE);}@Implementation protected void close(){}}
    WorkTestSupport w;long book;String id;
    @Before public void setup()throws Exception{w=new WorkTestSupport();book=w.book("Livro.pdf","Fixture renderer; real OCR models have a separate host test.");Files.copy(new File("tests/ocr/models/por.traineddata").toPath(),OcrEngine.model(w.app,"por").toPath(),StandardCopyOption.REPLACE_EXISTING);OcrToolsTest.Engine.output="Texto reconhecido desta página.";OcrToolsTest.Engine.during=null;OcrToolsTest.Engine.released=false;id=w.job("ocr",new JSONObject().put("uri",StudyFileProvider.uri(w.app,book).toString()).put("name","Livro.pdf").put("mime","application/pdf").put("language","por").put("material",book));try(TaskStore db=new TaskStore(w.app)){for(int page=0;page<3;page++)db.add(id,page,StudyFileProvider.uri(w.app,book).toString(),"Página "+(page+1),0,0);}}
    @After public void close(){OcrToolsTest.Engine.during=null;w.close();}
    @Test public void batchCommitsOneResultPerPageAndRecordsConfidence()throws Exception{w.run(id);assertEquals(3,w.items(id,"done"));String uri=StudyFileProvider.uri(w.app,book).toString();for(int page=0;page<3;page++)assertEquals("Texto reconhecido desta página.",OcrCache.row(w.app,uri,page).s("value"));try(TaskStore db=new TaskStore(w.app)){assertTrue(db.items(id,"done",0,1).get(0).s("message").contains("95%"));}assertTrue(OcrToolsTest.Engine.released);}
    @Test public void cancellingTheSecondPageKeepsTheFirstAndResumesTheOthers()throws Exception{TaskService.Control control=w.control(id);int[] calls={0};OcrToolsTest.Engine.during=()->{if(++calls[0]==2)control.stopped=true;};try(TaskStore db=new TaskStore(w.app)){try{TaskWork.run(w.service,db.job(id),db,control);fail();}catch(InterruptedIOException expected){}}assertEquals(1,w.items(id,"done"));OcrToolsTest.Engine.during=()->calls[0]++;w.run(id);assertEquals(3,w.items(id,"done"));assertEquals(4,calls[0]);}
    @Test public void correctedOcrTextIsWhatTheSpeechSourceReads()throws Exception{File file=new File(w.book(book).s("path"));Files.copy(new File(System.getProperty("seeky.pdf.fixture")).toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING);String hash=StudyFiles.hash(file),uri=StudyFileProvider.uri(w.app,book).toString();OcrCache.save(w.app,uri,0,hash,"Texto corrigido pelo utilizador.");try(SpeechDocument source=new SpeechDocument(w.app,android.net.Uri.parse(uri),"Livro.pdf","application/pdf",()->false)){assertEquals("Texto corrigido pelo utilizador.",source.part(0));}assertTrue(w.app.getSharedPreferences("reading_tools",0).getBoolean("index_dirty",false));}
}
